// StepConfig defines model for StepConfig.
//
// One step in a workflow, backed by a single connector.
//
// A connector is the compliance provider integration that does the work — `kyt_trmlabs` is TRM Labs. The step declares which operations that connector handles; a screening naming an operation no step is configured for is refused, and the error reports the supported set.
type StepConfig struct {
	// Unique within the workflow.
	StepID string `json:"stepId"`
	// Identifies which connector this step invokes.
	ConnectorID string `json:"connectorId"`
	// One entry per operation the step's connector handles.
	Operations []StepOperationConfig `json:"operations"`
	// Execution order among the workflow's steps, lowest first.
	Order int64 `json:"order"`
}

// StepOperationConfig defines model for StepOperationConfig.
//
// Configuration for one operation the step's connector handles. The operation arrives on the screening request; the connector decides how to handle it.
//
// Two rule sets govern the step, and both are configured here rather than sent per request, so the same call behaves differently across workflows. Trigger rules decide whether the connector runs at all; outcome rules turn the provider's response into the step's verdict. With neither configured the step runs under the connector's own defaults, which for `kyt_trmlabs` are permissive: the screening completes without consulting the provider.
//
// The four parameter lists are the contract for writing those rules: a rule naming a field outside `triggerRuleParameters` or `outcomeEvaluationParameters` is rejected. They are derived from the connector registry rather than stored, so a connector gaining a field is reflected here without a migration.
type StepOperationConfig struct {
	Operation *ScreeningOperationEnum `json:"operation,omitempty"`
	// Resolved server-side on every `GetWorkflow` call from the step's connector definition for this operation. Read-only: ignored on write.
	RequiredParameters []string `json:"requiredParameters,omitempty"`
	// Like `requiredParameters`, but optional inputs to the operation.
	OptionalParameters []string `json:"optionalParameters,omitempty"`
	// Fields a condition in `triggerRuleSetStruct` may reference.
	TriggerRuleParameters []string `json:"triggerRuleParameters,omitempty"`
	// Provider response fields a condition in `outcomeRuleSetStruct` may reference.
	OutcomeEvaluationParameters []string `json:"outcomeEvaluationParameters,omitempty"`
	// Additional provider response fields returned with the result; not usable in `outcomeRuleSetStruct` conditions.
	OutcomeMetaParameters []string `json:"outcomeMetaParameters,omitempty"`
	TriggerRuleSetStruct  *RuleSet `json:"triggerRuleSetStruct,omitempty"`
	// The tenant's trigger rules, as a JSON-encoded string. Set for steps whose rules are still defined as a legacy screening policy rather than natively in Compliance Orchestrator, and refreshed on every read. Mutually exclusive with `triggerRuleSetStruct`.
	TriggerRuleSetJSON   *string  `json:"triggerRuleSetJson,omitempty"`
	OutcomeRuleSetStruct *RuleSet `json:"outcomeRuleSetStruct,omitempty"`
	// The tenant's outcome rules, as a JSON-encoded string. Set for steps whose rules are still defined as a legacy screening policy rather than natively in Compliance Orchestrator, and refreshed on every read. Mutually exclusive with `outcomeRuleSetStruct`.
	OutcomeRuleSetJSON *string `json:"outcomeRuleSetJson,omitempty"`
}

// StepResult defines model for StepResult.
//
// The result of one workflow step's execution during a screening.
//
// Carries the step's outcome next to the two rule evaluations that produced it — which trigger rule decided the connector should run, and which outcome rule read the response — plus the provider's own verdict and risk level.
//
// A step that did not screen carries a `bypassReason` instead of a risk level. Only `PASSED_BY_POLICY` means the policy deliberately let it through; every other reason means the check could not be performed, and the step is rejected rather than passed. A bypass is not an approval.
type StepResult struct {
	// Identifier of this step within the workflow.
	StepID string `json:"stepId"`
	// Identifier of the connector that executed this step.
	ConnectorID        string                 `json:"connectorId"`
	Operation          ScreeningOperationEnum `json:"operation"`
	TriggerRuleOutcome TriggerRuleOutcomeEnum `json:"triggerRuleOutcome"`
	MatchedTriggerRule *Rule                  `json:"matchedTriggerRule,omitempty"`
	OutcomeRuleOutcome ScreeningOutcomeEnum   `json:"outcomeRuleOutcome"`
	MatchedOutcomeRule *Rule                  `json:"matchedOutcomeRule,omitempty"`
	Outcome            ScreeningOutcomeEnum   `json:"outcome"`
	Metadata           StepResultMetadata     `json:"metadata,omitempty"`
	// The connector-side screening ticket identifier.
	TicketID        *string               `json:"ticketId,omitempty"`
	Verdict         *ConnectorVerdictEnum `json:"verdict,omitempty"`
	ConnectorStatus *ConnectorStatusEnum  `json:"connectorStatus,omitempty"`
	BypassReason    *BypassReasonEnum     `json:"bypassReason,omitempty"`
	Risk            *RiskLevelEnum        `json:"risk,omitempty"`
}

// StepResultMetadata defines model for StepResultMetadata.
//
// Connector-specific data, keyed by the connector's configured outcomeMetaParameters for this operation.
type StepResultMetadata map[string]any

